  '{i}. {stitek} {stitek2} · {navstev}× ve {dny} dnech, celkem {celkem} · obvykle {hodiny} · {c}': '{i}. {stitek} {stitek2} · {navstev}× on {dny} days, total {celkem} · usually {hodiny} · {c}',
